/* Generated by postbuild.ts. New workers wait until the previous visit has ended. */
const CACHE_PREFIX = "changle-shell-";
const CACHE_NAME = CACHE_PREFIX + __VERSION__;
const SHELL = __SHELL__;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(SHELL.map((url) => new Request(url, { cache: "reload" })));
    // Pages redirects /index.html to /. A redirected Response cannot satisfy a
    // navigation whose redirect mode is manual; store an ordinary shell response.
    const index = await cache.match("/index.html");
    if (index.redirected) {
      const headers = new Headers(index.headers);
      headers.delete("Content-Encoding");
      headers.delete("Content-Length");
      await cache.put("/index.html", new Response(await index.arrayBuffer(), {
        status: index.status, statusText: index.statusText, headers,
      }));
    }
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin ||
      !/^https?:$/.test(url.protocol) || /^\/(eat|when|go|trip|hide|party|hang-on)(\/|$)/.test(url.pathname) ||
      request.headers.get("Upgrade")?.toLowerCase() === "websocket") return;

  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        // Do not let the HTTP cache pin a page to an earlier build.
        return await fetch(new Request(request, { cache: "no-cache" }));
      } catch {
        return (await caches.open(CACHE_NAME)).match("/index.html");
      }
    })());
  } else if (url.pathname.startsWith("/assets/")) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(request);
      if (cached) return cached;
      const response = await fetch(request);
      // A missing old chunk can be an HTML fallback: let freshness.ts handle that failure.
      if (response.ok && response.type === "basic" && !response.headers.get("Content-Type")?.includes("text/html")) {
        await cache.put(request, response.clone());
      }
      return response;
    })());
  }
});
